phase1.code:
# Nested conditionals — if statements inside if statements

player_health = 80
player_mana = 30
has_potion = True

# Basic nested if
if player_health < 50:
    print("Low health!")
    if has_potion:
        print("Using potion...")
        player_health = 100
        print(f"Health restored to {player_health}!")
    else:
        print("No potion! Run!")
else:
    print("Health is fine.")

# Deeper nesting (careful!)
enemy_type = "dragon"
player_level = 15

if enemy_type == "dragon":
    print("It's a dragon!")
    if player_level >= 20:
        print("You can fight it!")
        if player_health > 50:
            print("You're ready!")
        else:
            print("Heal first!")
    else:
        print("You're too weak! Run!")
else:
    print("It's just a goblin.")

# Alternative: use logical operators
if enemy_type == "dragon" and player_level >= 20 and player_health > 50:
    print("You can fight the dragon!")

print("\nGame continues...")

